insert into public.homeowner_programs (id, name, scope, bucket, summary, access, contact, status, sort_order, source) values
('my-safe-florida-home-msfh', 'My Safe Florida Home (MSFH)', 'statewide', 'Money to strengthen your home before the storm', 'A free wind-mitigation inspection of your home, then a grant of up to $10,000 toward approved wind-hardening upgrades. Most property owners get a 2-to-1 match — the state pays $2 for every $1 you spend — and low-income owners can qualify with no match required. The 2026 state budget put roughly $378 million back into the program, and the application portal is open for the 2026–27 year.', '["Apply free at mysafeflhome.com \u2014 it takes minutes.", "The state schedules your free wind-mitigation inspection and sends a report of qualifying upgrades.", "Once your grant is approved \u2014 and only then \u2014 choose a contractor and complete the work.", "Submit invoices for reimbursement. We help our clients with quotes, wind-mitigation documentation, and closeout paperwork."]'::jsonb, '[{"label": "mysafeflhome.com", "href": "https://mysafeflhome.com"}]'::jsonb, 'Open now', 0, 'covenantbuilders.org/homeowner-programs'),
('my-safe-florida-condo-pilot', 'My Safe Florida Condo (pilot)', 'statewide', 'Money to strengthen your home before the storm', 'The condominium version of MSFH for buildings three habitable stories and up. The association applies — not individual unit owners — and grants fund wind-hardening of common elements like roofs and openings. The pilot continues with about $27 million in fresh 2026 funding. If your board is already planning milestone or SIRS repairs, this can offset the hardening portion of the project.', '["Your association board applies at mysafeflcondo.com.", "Ask us how the pilot pairs with milestone inspection repairs \u2014 we work with condo boards across the Treasure Coast."]'::jsonb, '[{"label": "mysafeflcondo.com", "href": "https://mysafeflcondo.com"}]'::jsonb, 'Open now', 1, 'covenantbuilders.org/homeowner-programs'),
('weatherization-assistance-program-wap', 'Weatherization Assistance Program (WAP)', 'statewide', 'Money to strengthen your home before the storm', 'Free energy-related repairs — insulation, air sealing, A/C and water-heater work — for income-qualified households, delivered through local community agencies under FloridaCommerce. The local provider for your county is listed in the regional sections below.', '["Find your county\u2019s provider through the FloridaCommerce locator, or use the regional listings below."]'::jsonb, '[{"label": "FloridaCommerce \u2014 Weatherization", "href": "https://www.floridajobs.org/community-planning-and-development/community-services/weatherization-assistance-program"}]'::jsonb, 'Open now', 2, 'covenantbuilders.org/homeowner-programs'),
('elevate-florida-fdem', 'Elevate Florida (FDEM)', 'statewide', 'Money to strengthen your home before the storm', 'The state’s home-elevation and mitigation-reconstruction program drew over 12,000 applications in early 2025 and has been closed to new applications since April 2025, with existing awards delayed in federal review. We list it so you don’t chase it: if you already applied, check your status; if you didn’t, My Safe Florida Home is the live hardening option.', '["Existing applicants only: check status through the Elevate Florida portal or call 877-353-8835."]'::jsonb, '[{"label": "floridadisaster.org \u2014 Elevate Florida", "href": "https://www.floridadisaster.org/dem/mitigation/elevate-Florida/"}, {"label": "877-353-8835", "href": ""}]'::jsonb, 'Closed to new applicants', 3, 'covenantbuilders.org/homeowner-programs'),
('dfs-residential-property-mediation', 'DFS Residential Property Mediation', 'statewide', 'Free state help with insurance disputes', 'A free, state-run mediation program for residential property claims. The insurance company pays the entire cost. A neutral mediator is assigned within about three weeks, and many disputes settle at the conference. If you reach a settlement, you even have three business days to change your mind.', '["Call the DFS consumer helpline at 1-877-693-5236 (1-877-MY-FL-CFO) and ask for property insurance mediation.", "Or request it online through the Department of Financial Services."]'::jsonb, '[{"label": "myfloridacfo.com \u2014 Mediation", "href": "https://www.myfloridacfo.com/division/consumers/mediation"}, {"label": "1-877-693-5236", "href": ""}]'::jsonb, 'Open now', 4, 'covenantbuilders.org/homeowner-programs'),
('dfs-consumer-helpline', 'DFS Consumer Helpline', 'statewide', 'Free state help with insurance disputes', 'The general front door for any insurance problem: coverage questions, complaints about slow adjusters, or help understanding the Homeowner Claims Bill of Rights. A state insurance specialist opens a file, and your carrier must respond to the state.', '["Call 1-877-693-5236, Monday through Friday, or file a complaint online at myfloridacfo.com."]'::jsonb, '[{"label": "myfloridacfo.com", "href": "https://www.myfloridacfo.com/division/consumers"}, {"label": "1-877-693-5236", "href": ""}]'::jsonb, 'Open now', 5, 'covenantbuilders.org/homeowner-programs'),
('county-ship-programs', 'County SHIP Programs', 'statewide', 'Repair money for families who need it', 'Every Florida county runs a State Housing Initiatives Partnership office offering owner-occupied repair and rehabilitation help — roofs, HVAC, electrical, accessibility — for income-qualified residents. Funding windows open and close fast, and each county runs its own rules. See the Treasure Coast, Space Coast, and Orlando sections below for every local office, phone number, and current status.', '["Jump to your county below \u2014 each listing includes the office, phone, and whether applications are open right now."]'::jsonb, '[{"label": "Treasure Coast SHIP offices", "href": "#treasure-coast"}, {"label": "Space Coast", "href": "#space-coast"}, {"label": "Orlando area", "href": "#orlando-area"}]'::jsonb, 'Varies by county', 6, 'covenantbuilders.org/homeowner-programs'),
('usda-section-504-home-repair', 'USDA Section 504 Home Repair', 'statewide', 'Repair money for families who need it', 'For homes in USDA-eligible rural areas — which includes much of our service area outside the coastal cities — the USDA offers repair loans of up to $40,000 at 1% interest over 20 years, and grants of up to $10,000 for property owners 62 and older who cannot repay a loan (up to $15,000 in presidentially declared disaster areas).', '["Visit rd.usda.gov and search \u201csingle family housing repair,\u201d or contact the USDA Rural Development office serving Florida. Applications are accepted year-round."]'::jsonb, '[{"label": "rd.usda.gov", "href": "https://www.rd.usda.gov/programs-services/single-family-housing-programs/single-family-housing-repair-loans-grants"}]'::jsonb, 'Open now', 7, 'covenantbuilders.org/homeowner-programs'),
('fema-sba-after-a-declared-disaster', 'FEMA & SBA (after a declared disaster)', 'statewide', 'Repair money for families who need it', 'When a hurricane brings a federal disaster declaration, two doors open fast: FEMA grants for uninsured essential repairs, and SBA low-interest disaster loans for property owners. Many FEMA grants require an SBA application first — so the right move is to apply to both immediately.', '["Apply at disasterassistance.gov or call 1-800-621-3362 \u2014 typically within 60 days of the declaration.", "Apply for an SBA disaster loan at sba.gov/disaster at the same time."]'::jsonb, '[{"label": "disasterassistance.gov", "href": "https://www.disasterassistance.gov"}, {"label": "sba.gov/disaster", "href": "https://www.sba.gov/funding-programs/disaster-assistance"}, {"label": "1-800-621-3362", "href": ""}]'::jsonb, 'After declared disasters', 8, 'covenantbuilders.org/homeowner-programs'),
('rebuild-florida-cdbg-dr', 'Rebuild Florida (CDBG-DR)', 'statewide', 'Repair money for families who need it', 'The state’s long-term disaster rebuilding program repaired and replaced homes after Hurricanes Irma, Michael, and Ian — but it is no longer accepting new applications. If you applied after Hurricane Ian, you can still check your application status.', '["Existing applicants: call 1-800-915-6803 or check ian.rebuildflorida.gov."]'::jsonb, '[{"label": "ian.rebuildflorida.gov", "href": "https://ian.rebuildflorida.gov/"}, {"label": "1-800-915-6803", "href": ""}]'::jsonb, 'Closed to new applicants', 9, 'covenantbuilders.org/homeowner-programs'),
('homestead-exemption', 'Homestead Exemption', 'statewide', 'Property-tax relief and federal benefits most owners miss', 'Up to $50,000 off your home’s assessed value, plus the Save Our Homes cap that limits assessment increases to 3% a year. File once with your county property appraiser by March 1. Worth watching: a constitutional amendment on the November 2026 ballot would increase the homestead exemption further.', '["File with your county property appraiser \u2014 each county\u2019s contact is listed in the regional sections below."]'::jsonb, '[{"label": "floridarevenue.com \u2014 Property Tax Exemptions", "href": "https://floridarevenue.com/property/Pages/Taxpayers_Exemptions.aspx"}]'::jsonb, 'Open now', 10, 'covenantbuilders.org/homeowner-programs'),
('catastrophic-event-tax-refund-form-dr-465', 'Catastrophic-Event Tax Refund (Form DR-465)', 'statewide', 'Property-tax relief and federal benefits most owners miss', 'If a hurricane, flood, tornado, or fire makes your home uninhabitable for 30 days or more, Florida law (s. 197.319) entitles you to a prorated refund of that year’s property taxes. File sworn Form DR-465 with your county property appraiser by March 1 of the following year, with utility bills, insurance records, or permits as proof.', '["Download Form DR-465 and file it with your county property appraiser \u2014 not the tax collector.", "Keep utility bills and repair permits: they prove the days your home was uninhabitable."]'::jsonb, '[{"label": "Form DR-465 (PDF)", "href": "https://floridarevenue.com/property/Documents/dr465.pdf"}]'::jsonb, 'Open now', 11, 'covenantbuilders.org/homeowner-programs'),
('rebuild-without-a-tax-increase-calamity-rule', 'Rebuild Without a Tax Increase (Calamity Rule)', 'statewide', 'Property-tax relief and federal benefits most owners miss', 'If your homesteaded home is damaged by a storm or other calamity, you can rebuild it — even slightly larger — without your assessed value going up, as long as the new square footage stays within 130% of the original (or 2,000 sq ft if greater) and you start within about five years. Your property appraiser applies this when you rebuild.', '["Tell your county property appraiser you are rebuilding after storm damage and ask for the s. 193.155 calamity treatment."]'::jsonb, '[{"label": "Florida Statute 193.155", "href": "https://www.flsenate.gov/laws/statutes/2025/193.155"}]'::jsonb, 'Open now', 12, 'covenantbuilders.org/homeowner-programs'),
('permanent-hurricane-supply-tax-exemption', 'Permanent Hurricane-Supply Tax Exemption', 'statewide', 'Property-tax relief and federal benefits most owners miss', 'Florida ended its temporary disaster-preparedness sales-tax holidays and instead made key hurricane supplies permanently tax-free as of August 2025 — batteries, certain portable generators, smoke and carbon-monoxide detectors, and more, every day of the year.', '[]'::jsonb, '[{"label": "floridarevenue.com \u2014 current exempt items", "href": "https://floridarevenue.com/pages/default.aspx"}]'::jsonb, 'Open now', 13, 'covenantbuilders.org/homeowner-programs'),
('va-disability-housing-grants-sah-sha', 'VA Disability Housing Grants (SAH / SHA)', 'statewide', 'Property-tax relief and federal benefits most owners miss', 'Veterans with qualifying service-connected disabilities can receive substantial federal grants to buy, build, or modify a home — Specially Adapted Housing grants run up to about $126,000 and Special Home Adaptation grants up to about $25,000 for fiscal year 2026, usable up to six times over a lifetime.', '["Apply online at VA.gov under housing assistance, or through your VSO."]'::jsonb, '[{"label": "va.gov \u2014 Disability Housing Grants", "href": "https://www.va.gov/housing-assistance/disability-housing-grants/"}]'::jsonb, 'Open now', 14, 'covenantbuilders.org/homeowner-programs'),
('irs-casualty-loss-deduction', 'IRS Casualty-Loss Deduction', 'statewide', 'Property-tax relief and federal benefits most owners miss', 'After a federally declared disaster, uninsured losses to your home can be deductible on your federal return (Form 4684) — and you can elect to claim them on the prior year’s return for a faster refund. One conversation with your tax preparer can be worth thousands.', '[]'::jsonb, '[{"label": "irs.gov \u2014 Topic 515", "href": "https://www.irs.gov/taxtopics/tc515"}]'::jsonb, 'Open now', 15, 'covenantbuilders.org/homeowner-programs'),
('indian-river-county-ship', 'Indian River County SHIP', 'Indian River County', 'Indian River, St. Lucie & Martin counties', 'Owner-occupied rehabilitation loans (standard and emergency), purchase assistance, and foreclosure-prevention help through County Community Services. The 2026–27 application window opened August 1, 2026 and runs until funds are gone — appointments only, no walk-ins.', '[]'::jsonb, '[{"label": "indianriver.gov \u2014 SHIP", "href": "https://indianriver.gov/services/community_services/state_housing_initiative_partnership_program/index.php"}, {"label": "(772) 226-1870", "href": ""}]'::jsonb, 'Open now', 16, 'covenantbuilders.org/homeowner-programs'),
('indian-river-habitat-for-humanity-home-repair', 'Indian River Habitat for Humanity — Home Repair', 'Indian River County', 'Indian River, St. Lucie & Martin counties', 'Repairs for roughly 80 working families, seniors, and veterans a year. Apply through the main office on US-1 in Vero Beach.', '[]'::jsonb, '[{"label": "irchabitat.org", "href": "https://www.irchabitat.org/our-programs/"}, {"label": "(772) 562-9860", "href": ""}]'::jsonb, 'Open now', 17, 'covenantbuilders.org/homeowner-programs'),
('utility-bill-help-liheap', 'Utility-bill help (LIHEAP)', 'Indian River County', 'Indian River, St. Lucie & Martin counties', 'The Economic Opportunities Council of Indian River County handles energy-bill assistance from its Vero Beach office.', '[]'::jsonb, '[{"label": "eocofirc.net", "href": "https://eocofirc.net/liheap/"}, {"label": "(772) 562-4177", "href": ""}]'::jsonb, 'Call to check', 18, 'covenantbuilders.org/homeowner-programs'),
('property-appraiser-homestead-storm-damage-tax-relief', 'Property Appraiser (homestead & storm-damage tax relief)', 'Indian River County', 'Indian River, St. Lucie & Martin counties', 'File homestead exemptions, DR-465 storm refunds, and calamity-rebuild treatment here.', '[]'::jsonb, '[{"label": "ircpa.org", "href": "https://www.ircpa.org/"}, {"label": "(772) 226-1469", "href": ""}]'::jsonb, 'Open now', 19, 'covenantbuilders.org/homeowner-programs'),
('city-of-fort-pierce-ship-rehabilitation-purchase-assistance', 'City of Fort Pierce — SHIP Rehabilitation & Purchase Assistance', 'St. Lucie County', 'Indian River, St. Lucie & Martin counties', 'City-limits residents: applications open October 1, 2026 at 8 a.m., and a mandatory orientation in September comes first (rehab sessions Sept 8 or 22; purchase sessions Sept 3 or 17). First submitted, first qualified — go to orientation and be ready on day one.', '[]'::jsonb, '[{"label": "cityoffortpierce.com \u2014 Grants Administration", "href": "https://www.cityoffortpierce.com/170/Grants-Administration"}, {"label": "(772) 467-3161", "href": ""}]'::jsonb, 'Opens Oct 1, 2026', 20, 'covenantbuilders.org/homeowner-programs'),
('st-lucie-county-housing-rehabilitation-ship', 'St. Lucie County Housing Rehabilitation (SHIP)', 'St. Lucie County', 'Indian River, St. Lucie & Martin counties', 'Roof, HVAC, and septic repair or replacement for owner-occupied homes with failing systems. The 2026 window filled its 20-application cap in May — check back for the next opening.', '[]'::jsonb, '[{"label": "stlucieco.gov \u2014 Housing Rehabilitation", "href": "https://www.stlucieco.gov/departments-and-services/community-services/housing/housing-rehabilitation-assistance"}, {"label": "(772) 462-1777", "href": ""}]'::jsonb, 'Closed / waitlist', 21, 'covenantbuilders.org/homeowner-programs'),
('port-st-lucie-homeowner-repair-rehabilitation', 'Port St. Lucie — Homeowner Repair & Rehabilitation', 'St. Lucie County', 'Indian River, St. Lucie & Martin counties', 'Code, safety, hurricane-shutter, and accessibility repairs for city residents. Demand is intense: the 2026 pre-application list filled 100 slots in ten minutes the morning it opened in February. Mark your calendar for early 2027 and apply the minute it opens.', '[]'::jsonb, '[{"label": "cityofpsl.com \u2014 Housing Programs", "href": "https://www.cityofpsl.com/Government/Your-City-Government/Departments/Neighborhood-Services/Community-Programs/Housing-Programs/Homeowner-Repair-Rehabilitation-Assistance-Program"}, {"label": "(772) 344-4084", "href": ""}]'::jsonb, 'Closed / waitlist', 22, 'covenantbuilders.org/homeowner-programs'),
('self-solar-and-energy-loan-fund', 'SELF — Solar and Energy Loan Fund', 'St. Lucie County', 'Indian River, St. Lucie & Martin counties', 'A Fort Pierce-based nonprofit lender for roof repair, impact windows and doors, shutters, A/C, and solar — built for property owners banks turn down. A strong option when grant windows are closed.', '[]'::jsonb, '[{"label": "solarenergyloanfund.org", "href": "https://www.solarenergyloanfund.org"}, {"label": "(772) 468-1818", "href": ""}]'::jsonb, 'Open now', 23, 'covenantbuilders.org/homeowner-programs'),
('st-lucie-habitat-repair-a-home', 'St. Lucie Habitat — Repair A Home', 'St. Lucie County', 'Indian River, St. Lucie & Martin counties', 'Critical repairs through affordable repayable loans. Not accepting new repair applications at the moment — call to ask about the next intake.', '[]'::jsonb, '[{"label": "stluciehabitat.org", "href": "https://stluciehabitat.org/repair-a-home/"}, {"label": "(772) 464-1117", "href": ""}]'::jsonb, 'Paused — check back', 24, 'covenantbuilders.org/homeowner-programs'),
('property-appraiser-homestead-storm-damage-tax-relief-st-luci', 'Property Appraiser (homestead & storm-damage tax relief)', 'St. Lucie County', 'Indian River, St. Lucie & Martin counties', 'Offices in Fort Pierce and Port St. Lucie.', '[]'::jsonb, '[{"label": "paslc.gov", "href": "https://www.paslc.gov/"}, {"label": "(772) 462-1000", "href": ""}]'::jsonb, 'Open now', 25, 'covenantbuilders.org/homeowner-programs'),
('martin-county-ship-cdbg-housing-rehabilitation', 'Martin County SHIP & CDBG Housing Rehabilitation', 'Martin County', 'Indian River, St. Lucie & Martin counties', 'Roof, HVAC, and septic repairs plus code, safety, and hurricane-hardening work for income-qualified owners. Both programs are between funding windows right now — get on the county’s radar so you hear when applications reopen.', '[]'::jsonb, '[{"label": "martin.fl.us/SHIP", "href": "https://www.martin.fl.us/SHIP"}, {"label": "(772) 288-5785", "href": ""}]'::jsonb, 'Closed / waitlist', 26, 'covenantbuilders.org/homeowner-programs'),
('habitat-for-humanity-of-martin-county', 'Habitat for Humanity of Martin County', 'Martin County', 'Indian River, St. Lucie & Martin counties', 'Runs neighborhood revitalization and the A Brush with Kindness exterior repair program with the City of Stuart. Call for current repair-program availability.', '[]'::jsonb, '[{"label": "habitatmartin.org", "href": "https://www.habitatmartin.org/"}, {"label": "(772) 223-9940", "href": ""}]'::jsonb, 'Call to check', 27, 'covenantbuilders.org/homeowner-programs'),
('property-appraiser-homestead-storm-damage-tax-relief-martin-', 'Property Appraiser (homestead & storm-damage tax relief)', 'Martin County', 'Indian River, St. Lucie & Martin counties', 'On Willoughby Blvd. in Stuart.', '[]'::jsonb, '[{"label": "pamartinfl.gov", "href": "https://www.pamartinfl.gov/"}, {"label": "(772) 288-5608", "href": ""}]'::jsonb, 'Open now', 28, 'covenantbuilders.org/homeowner-programs'),
('brevard-county-repair-rehabilitation-reconstruction-ship', 'Brevard County Repair, Rehabilitation & Reconstruction (SHIP)', 'County & city programs', 'Brevard County', 'Roof repair, window replacement, plumbing, electrical, insulation, and accessibility work for owner-occupied homes in unincorporated Brevard and non-participating cities like Rockledge. Currently open and accepting applications through the county’s online portal.', '[]'::jsonb, '[{"label": "brevardfl.gov \u2014 Housing Programs", "href": "https://www.brevardfl.gov/HousingAndHumanServices/HousingPrograms/ReplaceRehabAndRepairProgram"}, {"label": "(321) 633-2007", "href": ""}]'::jsonb, 'Open now', 29, 'covenantbuilders.org/homeowner-programs'),
('city-of-melbourne-homeowner-rehabilitation', 'City of Melbourne — Homeowner Rehabilitation', 'County & city programs', 'Brevard County', 'Deferred-loan rehabilitation up to $95,000 to bring homes to code, and reconstruction assistance up to $107,000. Pre-applications are being accepted through the city’s online portal.', '[]'::jsonb, '[{"label": "melbourneflorida.org \u2014 Housing Programs", "href": "https://www.melbourneflorida.org/Government/Departments/Community-Development/Housing-Urban-Improvement/Housing-Programs"}, {"label": "(321) 608-7530", "href": ""}]'::jsonb, 'Open now', 30, 'covenantbuilders.org/homeowner-programs'),
('city-of-titusville-rehabilitation-assistance', 'City of Titusville — Rehabilitation Assistance', 'County & city programs', 'Brevard County', 'Owner-occupied housing repair through the Neighborhood Services housing division — first qualified, first served, and taking applications until funds are committed.', '[]'::jsonb, '[{"label": "titusville.com \u2014 Rehabilitation Assistance", "href": "https://titusville.com/415/Rehabilitation-Assistance-Program"}, {"label": "(321) 567-3997", "href": ""}]'::jsonb, 'Open now', 31, 'covenantbuilders.org/homeowner-programs'),
('city-of-palm-bay-housing-rehabilitation', 'City of Palm Bay — Housing Rehabilitation', 'County & city programs', 'Brevard County', 'Rehabilitation up to $75,000 as a forgivable deferred loan, plus emergency repair and disaster assistance — but the SHIP waitlist is closed. Watch the city’s news page for short reopening windows.', '[]'::jsonb, '[{"label": "palmbayfl.gov \u2014 Housing Programs", "href": "https://www.palmbayfl.gov/government/city-departments-f-to-z/housing-programs/programs"}, {"label": "(321) 726-5633", "href": ""}]'::jsonb, 'Closed / waitlist', 32, 'covenantbuilders.org/homeowner-programs'),
('city-of-cocoa-housing-rehabilitation', 'City of Cocoa — Housing Rehabilitation', 'County & city programs', 'Brevard County', 'Repair, rehabilitation, and reconstruction up to $75,000 as a deferred loan. Currently closed to new applications.', '[]'::jsonb, '[{"label": "cocoafl.gov \u2014 Housing Rehabilitation", "href": "https://www.cocoafl.gov/294/Housing-Rehabilitation-Program"}, {"label": "(321) 433-8525", "href": ""}]'::jsonb, 'Closed / waitlist', 33, 'covenantbuilders.org/homeowner-programs'),
('space-coast-habitat-for-humanity-home-repairs', 'Space Coast Habitat for Humanity — Home Repairs', 'County & city programs', 'Brevard County', 'Critical home repair for veterans and a preservation program for owner-occupants at 30–80% of area median income. New repair applications are paused — check back or call.', '[]'::jsonb, '[{"label": "spacecoasthabitat.org", "href": "https://www.spacecoasthabitat.org/programs/home-repairs/"}, {"label": "(321) 728-4009", "href": ""}]'::jsonb, 'Paused — check back', 34, 'covenantbuilders.org/homeowner-programs'),
('property-appraiser-homestead-storm-damage-tax-relief-county-', 'Property Appraiser (homestead & storm-damage tax relief)', 'County & city programs', 'Brevard County', 'Offices in Titusville, Viera, Melbourne, and Palm Bay; the site takes storm-damage value-review requests directly.', '[]'::jsonb, '[{"label": "bcpao.us", "href": "https://www.bcpao.us/"}, {"label": "(321) 264-6700", "href": ""}]'::jsonb, 'Open now', 35, 'covenantbuilders.org/homeowner-programs'),
('orange-county-housing-rehabilitation-ship', 'Orange County Housing Rehabilitation (SHIP)', 'Orange County & City of Orlando', 'Orange, Osceola, Seminole & Lake counties', 'Repairs that eliminate health, safety, and code hazards for very-low-income property owners who have owned and occupied the home at least a year. Applications are open through the county’s online portal.', '[]'::jsonb, '[{"label": "orangecountyfl.net \u2014 Housing Rehabilitation", "href": "https://www.orangecountyfl.net/NeighborsHousing/HousingRehabilitation.aspx"}, {"label": "(407) 836-5150", "href": ""}]'::jsonb, 'Open now', 36, 'covenantbuilders.org/homeowner-programs'),
('habitat-orlando-osceola-home-preservation-roof-replacement', 'Habitat Orlando & Osceola — Home Preservation & Roof Replacement', 'Orange County & City of Orlando', 'Orange, Osceola, Seminole & Lake counties', 'Major repairs and full roof replacements at no cost to qualified Orange County property owners, in partnership with county government — more than 100 roofs replaced since 2019.', '[]'::jsonb, '[{"label": "habitatorlando.org", "href": "https://habitatorlando.org/"}, {"label": "(407) 648-4567", "href": ""}]'::jsonb, 'Open now', 37, 'covenantbuilders.org/homeowner-programs'),
('city-of-orlando-housing-rehabilitation-repair', 'City of Orlando — Housing Rehabilitation & Repair', 'Orange County & City of Orlando', 'Orange, Osceola, Seminole & Lake counties', 'City residents get one of the strongest programs in the state: health-and-safety repairs up to $20,000 as an outright grant with no lien, larger rehabilitation as deferred loans up to $100,000, and emergency roof, window, and plumbing repairs. Applications open online.', '[]'::jsonb, '[{"label": "orlando.gov \u2014 Housing Rehabilitation", "href": "https://www.orlando.gov/Building-Development/Housing-and-Development-Grants-Incentives-and-Assistance/Housing-Assistance-Programs/Apply-to-the-Housing-Rehabilitation-Program"}, {"label": "(407) 246-2708", "href": ""}]'::jsonb, 'Open now', 38, 'covenantbuilders.org/homeowner-programs'),
('utility-bill-help-liheap-orange-county-community-action', 'Utility-bill help (LIHEAP) — Orange County Community Action', 'Orange County & City of Orlando', 'Orange, Osceola, Seminole & Lake counties', 'Energy-bill and crisis assistance up to $1,000 a year for income-qualified households.', '[]'::jsonb, '[{"label": "orangecountyfl.net \u2014 Energy Bill Assistance", "href": "https://www.orangecountyfl.net/CommunityFamilyServices/EnergyBillAssistance.aspx"}, {"label": "(407) 836-7429", "href": ""}]'::jsonb, 'Open now', 39, 'covenantbuilders.org/homeowner-programs'),
('osceola-county-ship', 'Osceola County SHIP', 'Osceola County', 'Orange, Osceola, Seminole & Lake counties', 'Purchase assistance, owner-occupied rehabilitation, and foreclosure prevention are all closed due to funding availability — but the emergency repair program remains available for unincorporated Osceola and St. Cloud. Monitor the county site for reopening.', '[]'::jsonb, '[{"label": "osceola.org \u2014 SHIP", "href": "https://www.osceola.org/Services/Housing-Programs/SHIP"}, {"label": "(407) 742-8400", "href": ""}]'::jsonb, 'Emergency repairs only', 40, 'covenantbuilders.org/homeowner-programs'),
('osceola-council-on-aging-weatherization-liheap', 'Osceola Council on Aging — Weatherization & LIHEAP', 'Osceola County', 'Orange, Osceola, Seminole & Lake counties', 'Free weatherization (insulation, duct and HVAC repair, air sealing) for both Osceola and Orange counties, plus energy-bill assistance for Osceola residents.', '[]'::jsonb, '[{"label": "osceolagenerations.org", "href": "https://osceolagenerations.org/"}, {"label": "(407) 846-8532", "href": ""}]'::jsonb, 'Open now', 41, 'covenantbuilders.org/homeowner-programs'),
('seminole-county-ship-minor-repair-rehabilitation', 'Seminole County SHIP (Minor Repair & Rehabilitation)', 'Seminole County', 'Orange, Osceola, Seminole & Lake counties', 'Minor home repair and full rehabilitation programs exist but are currently closed, and the purchase-assistance waitlist is closed with no reopening date. Check the county page for the next window.', '[]'::jsonb, '[{"label": "seminolecountyfl.gov \u2014 Community Development", "href": "https://www.seminolecountyfl.gov/departments-services/community-services/community-development/community-development-programs"}, {"label": "(407) 665-2300", "href": ""}]'::jsonb, 'Closed / waitlist', 42, 'covenantbuilders.org/homeowner-programs'),
('utility-bill-help-liheap-city-of-sanford', 'Utility-bill help (LIHEAP) — City of Sanford', 'Seminole County', 'Orange, Osceola, Seminole & Lake counties', 'Sanford administers energy-bill assistance for all Seminole County residents, by appointment.', '[]'::jsonb, '[{"label": "sanfordfl.gov \u2014 LIHEAP", "href": "https://sanfordfl.gov/government/community-relations/liheap/"}, {"label": "(407) 688-5166", "href": ""}]'::jsonb, 'Open now', 43, 'covenantbuilders.org/homeowner-programs'),
('meals-on-wheels-etc-weatherization', 'Meals on Wheels, Etc. — Weatherization', 'Seminole County', 'Orange, Osceola, Seminole & Lake counties', 'The weatherization provider for Seminole County — window sealing, weather stripping, ventilation, and efficiency upgrades for income-qualified homes.', '[]'::jsonb, '[{"label": "mealsetc.org", "href": "https://www.mealsetc.org/"}]'::jsonb, 'Call to check', 44, 'covenantbuilders.org/homeowner-programs'),
('lake-county-ship', 'Lake County SHIP', 'Lake County', 'Orange, Osceola, Seminole & Lake counties', 'Owner-occupied rehabilitation, demolition and replacement, and disaster mitigation with about $3 million in 2025–26 funding — first come, first qualified. Call to confirm the current intake before you count on it.', '[]'::jsonb, '[{"label": "lakecountyfl.gov \u2014 Housing", "href": "https://lakecountyfl.gov/housing/rehabilitation-and-replacement-programs"}, {"label": "(352) 742-6519", "href": ""}]'::jsonb, 'Call to check', 45, 'covenantbuilders.org/homeowner-programs'),
('habitat-for-humanity-lake-sumter-preservation-repair', 'Habitat for Humanity Lake-Sumter — Preservation & Repair', 'Lake County', 'Orange, Osceola, Seminole & Lake counties', 'Roof, window, and door repair or replacement, weatherization, electrical, plumbing, HVAC, and accessibility ramps for owner-occupants — open first come, first qualified, with a separate higher-income-limit repair program for City of Eustis residents.', '[]'::jsonb, '[{"label": "habitatls.org", "href": "https://habitatls.org/eustis-home-repair/"}, {"label": "(352) 483-0434", "href": ""}]'::jsonb, 'Open now', 46, 'covenantbuilders.org/homeowner-programs'),
('lake-community-action-agency-weatherization-liheap', 'Lake Community Action Agency — Weatherization & LIHEAP', 'Lake County', 'Orange, Osceola, Seminole & Lake counties', 'Energy-bill assistance and weatherization from the Eustis office, first come, first served while funds last.', '[]'::jsonb, '[{"label": "lakecaa.org", "href": "http://lakecaa.org"}, {"label": "(352) 357-5550", "href": ""}]'::jsonb, 'Open now', 47, 'covenantbuilders.org/homeowner-programs')
