-- Seed: the 48 homeowner programs from covenantbuilders.org/homeowner-programs.
-- Safe to re-run (upsert).
on conflict (id) do update set name=excluded.name, scope=excluded.scope, bucket=excluded.bucket, summary=excluded.summary, access=excluded.access, contact=excluded.contact, status=excluded.status, sort_order=excluded.sort_order, source=excluded.source;
